PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS sources (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, url TEXT NOT NULL, epg_url TEXT, enabled INTEGER NOT NULL DEFAULT 1, consecutive_failures INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), last_checked_at TEXT, last_success_at TEXT);
CREATE TABLE IF NOT EXISTS channels (id INTEGER PRIMARY KEY AUTOINCREMENT, source_id INTEGER NOT NULL REFERENCES sources(id) ON DELETE CASCADE, name TEXT NOT NULL, url TEXT NOT NULL, logo TEXT, category TEXT NOT NULL DEFAULT 'Geral', tvg_id TEXT, status TEXT NOT NULL CHECK(status IN ('online','offline')), last_checked_at TEXT, UNIQUE(source_id,url));
CREATE TABLE IF NOT EXISTS runs (id INTEGER PRIMARY KEY AUTOINCREMENT, source_count INTEGER NOT NULL, successful_count INTEGER NOT NULL, channel_count INTEGER NOT NULL DEFAULT 0, online_count INTEGER NOT NULL DEFAULT 0, failed_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', completed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checks (id INTEGER PRIMARY KEY AUTOINCREMENT, source_id INTEGER NOT NULL REFERENCES sources(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('success','failure')), channel_count INTEGER NOT NULL DEFAULT 0, error TEXT, checked_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO settings(key,value) VALUES ('playlistName','Minha playlist IPTV'),('epgUrl','');
CREATE TABLE IF NOT EXISTS removed_channels (id INTEGER PRIMARY KEY AUTOINCREMENT, source_name TEXT NOT NULL, channel_name TEXT NOT NULL, channel_url TEXT NOT NULL, removed_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS availability_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, online INTEGER NOT NULL, total INTEGER NOT NULL, captured_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS channel_staging (run_key TEXT NOT NULL, source_id INTEGER NOT NULL REFERENCES sources(id) ON DELETE CASCADE, name TEXT NOT NULL, url TEXT NOT NULL, logo TEXT, category TEXT NOT NULL, tvg_id TEXT, status TEXT NOT NULL CHECK(status IN ('online','offline')), UNIQUE(run_key,url));
